    "A01K67/00": {
      "code": "A01K67/00",
      "level": 7,
      "parent": null,
      "ja": "他に分類されない動物の飼育または繁殖；新規な動物<br><br><u>注</u><br><br>このグループにおいては，下記の用語は以下に示す意味で用いる：<br>―繁殖は動物を増やすことおよびその出産または孵化を含むことを意味する。",
      "en": "Rearing or breeding animals, not otherwise provided for; New or modified breeds of animals<br><br><u>NOTE</u><br><br>In this group the following term is used with the meaning indicated: <br>\"breeding\" means obtaining animals up to and including their birth or hatching.",
      "count": 366,
      "ipcCode": "A01K67/00",
      "coreCode": "A01K67/00",
      "note": "",
      "sourceFile": "cpc_A01K.txt",
      "kind": "cpc"
    },
    "A01K67/02": {
      "code": "A01K67/02",
      "level": 8,
      "parent": "A01K67/00",
      "ja": "脊椎動物の繁殖<br><br><u>注</u><br><br>新規なペプチドまたはペプチドをエンコードする新規なＤＮＡまたは対応するｍＲＮＡ，および遺伝子導入動物の獲得のためのそれらの使用に関連する文献は，ペプチドにより，適切なインデキシングコードを付してサブクラスＣ０７ＫまたはグループＣ１２Ｎ９／００に分類される",
      "en": "Breeding vertebrates<br><br><u>NOTE</u><br><br>Documents relating to new peptides or new DNA or its corresponding mRNA encoding for peptides and their use for the obtention of transgenic animals are classified in subclass C07K or in group C12N9/00 according to the peptides, and are given the appropriate Indexing Codes.",
      "count": 12512,
      "ipcCode": "A01K67/02",
      "coreCode": "A01K67/02",
      "note": "",
      "sourceFile": "cpc_A01K.txt",
      "kind": "cpc"
    },
    "A01K67/027": {
      "code": "A01K67/027",
      "level": 8,
      "parent": "A01K67/00",
      "ja": "新規な脊椎動物<br><br><u>注</u><br><br><br>グループＡ０１Ｋ６７／０２７においては，種によって特徴づけられる動物に関するＡ０１Ｋ２２２７／００およびサブグループのインデキシングコードを付加することが望ましい。グループＡ０１Ｋ６７／０２７においては，目的によって特徴づけられるＡ０１Ｋ２２６７／００およびサブグループのインデキシングコードを付加することが望ましい。",
      "en": "New or modified breeds of vertebrates<br><br><u>NOTE</u><br><br>In group A01K67/027, it is desirable to add the Indexing Codes of A01K2227/00 and subgroups relating to animals characterised by species and to add the Indexing Codes of A01K2267/00 and subgroups relating to animals characterised by their purpose. In groups A01K67/0275 - A01K67/0278, A01K67/61 and subgroups thereof, it is also desirable to add the Indexing Codes of A01K2217/00 and subgroups to characterise specific aspects of the genetically modified animals or the Indexing Codes of A01K2267/00 and subgroups to characterise the purpose of the animals.",
      "count": 2389,
      "ipcCode": "A01K67/027",
      "coreCode": "A01K67/027",
      "note": "",
      "sourceFile": "cpc_A01K.txt",
      "kind": "cpc"
    },
